"""Public regression controls. Do not edit this file to repair the importer."""
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest


class ImportContractTests(unittest.TestCase):
    def invoke(self, raw, *, fmt="csv", separator="|"):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "input"
            path.write_bytes(raw)
            result = subprocess.run([sys.executable, str(Path(__file__).with_name("importer.py")),
                "--input", str(path), "--format", fmt, "--course-separator", separator],
                capture_output=True, timeout=5)
            return result.returncode, json.loads(result.stdout)

    def test_existing_csv_success(self):
        code, value = self.invoke(b"id,name,courses\nA001,Alice,Math|Physics\n")
        self.assertEqual(code, 0)
        self.assertEqual(value["records"], [{"id": "A001", "name": "Alice", "courses": ["Math", "Physics"], "raw_courses": "Math|Physics"}])
        self.assertEqual(value["stats"], {"students": 1, "enrollments": 2})

    def test_bom_crlf_tsv_preserves_name(self):
        raw = "\ufeffcourses\tname\tid\r\n数学 ; 物理\t 小陈 \t A001 \r\n".encode()
        code, value = self.invoke(raw, fmt="tsv", separator=";")
        self.assertEqual(code, 0)
        self.assertEqual(value["records"][0], {"id": "A001", "name": " 小陈 ", "courses": ["数学", "物理"], "raw_courses": "数学 ; 物理"})

    def test_configuration_error(self):
        code, value = self.invoke(b"", separator="||")
        self.assertEqual((code, value["error"]["code"], value["error"]["row"]), (2, "E_CONFIG", None))

    def test_mixed_delimiter_precedes_empty_token(self):
        code, value = self.invoke(b"id,name,courses\nA001,Alice,Math;Physics|\n")
        self.assertEqual((code, value["error"]["code"], value["error"]["field"]), (2, "E_DELIMITER_MIXED", "courses"))

    def test_id_error_precedes_course_error_in_same_record(self):
        code, value = self.invoke(b"id,name,courses\n,Alice,Math||Physics\nA002,Bob,Math\n")
        self.assertEqual((code, value["error"]["code"], value["error"]["row"]), (2, "E_ID_EMPTY", 2))

    def test_escaped_course_delimiter_is_literal(self):
        code, value = self.invoke(b"id,name,courses\nA001,Alice,Math\\|Applied|Physics\n")
        self.assertEqual(code, 0)
        self.assertEqual(value["records"][0]["courses"], ["Math|Applied", "Physics"])

    def test_quoted_line_break_does_not_change_logical_record_number(self):
        raw = b'id,name,courses\nA001,"Alice\nSmith",Math\nA002,Bob,Math||Physics\n'
        code, value = self.invoke(raw)
        self.assertEqual((code, value["error"]["code"], value["error"]["row"]), (2, "E_COURSE_EMPTY", 3))


if __name__ == "__main__":
    unittest.main()
